  } else {
    days_per_month[1] = 28;
  }



  *outMM = 1;
  *outDD = inDDD;
  while( *outMM <= 12 && *outDD > days_per_month[*outMM - 1] ) {

    *outDD -= days_per_month[*outMM - 1];
    (*outMM)++;
  }
}

