        const double symprec)
{
  int i, j, k, l;
  double dot_product;

  for (i = 0; i < 3; i++) {
    for (j = i + 1; j < 3; j++) {
      dot_product = 0.0;
      for (k = 0; k < 3; k++) {
 dot_product += basis[i][k] * basis[j][k];
      }
      if (dot_product > symprec) {
 for (k = 0; k < 3; k++) {
   if (! (k == i || k == j)) {
     for (l = 0; l < 3; l++) {
       basis[k][l] += 2 * basis[i][l];
     }
     break;
   }
 }
 for (k = 0; k < 3; k++) {
   basis[i][k] = -basis[i][k];
 }
 return 0;
      }
    }
  }

  return 1;
}

