   while ((*magnitude & ~0x007FFFFF) == 0) {
      *magnitude <<= 1;
      (*exponent)--;



   }
   while (*magnitude & (~0x007FFFFF << 1)) {
      *magnitude >>= 1;
      (*exponent)++;

   }
   if (sign) {
   *magnitude = -*magnitude;
   }
}

