 return -2;
   }
   while (high < low) {
      middle = (high + low)/2;
      if (arr[middle] == key){
      return middle;
    }
      else if (low == middle || high == middle) {
         return high;
      }
      else if (arr[middle] < key)
      {low=middle;}
      else if (arr[middle] > key){
   high=middle;}
