        while (intPart)
        {
            *p++ = '0' + intPart % 10;
            intPart /= 10;
        }


        p1 = p;


        while (p > ptr)
        {
            c = *--p;
            *p = *ptr;
            *ptr++ = c;
        }


        ptr = p1;
    }


    if (precision)
    {

        *ptr++ = '.';


        while (precision--)
        {
            f *= (double)10.0;
            c = f;
            *ptr++ = '0' + c;
            f -= c;
        }
    }


    *ptr = 0;

    temp_str = --ptr;
    while(*temp_str != '.')
    {
        if(*temp_str == '0')
        {
            *temp_str = '\0';
        }
        else
        {
